def max_product(arr):
    n = len(arr)
    dp = [0] * n
    for i in range(n):
        dp[i] = arr[i]
        for j in range(i):
            if arr[j] < arr[i]:
                dp[i] = max(dp[i], dp[j] * arr[i])
    return max(dp)

